pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 amount) public {
        // Ensure we can call Command as Owner
        vm.assume(adr != address(0));
        // Fund the contract so it has some balance
        vm.deal(address(c), 1 ether);
        // Make the call to Command with some value
        vm.deal(address(this), amount);
        vm.prank(c.Owner());
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("Command(address,bytes)", adr, data));
        // After Command, call multiplicate with msg.value exactly equal to address(this).balance
        uint256 bal = address(c).balance;
        vm.deal(address(this), bal);
        vm.prank(address(this));
        (bool reverted, ) = address(c).call{value: bal}(abi.encodeWithSignature("multiplicate(address)", adr));
        // The property: multiplicate should revert when msg.value == address(this).balance
        assertTrue(reverted, "multiplicate should revert after Command call");
    }
}

