pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, bytes memory data, uint256 amount) public {
        vm.assume(adr != address(c) && adr != address(0));

        // Fund the contract with some initial balance
        vm.deal(address(c), 100 ether);

        // Record balance before Command call
        uint256 balanceBefore = address(c).balance;

        // Execute Command as owner
        vm.prank(c.Owner());
        c.Command{value: amount}(adr, data);

        // Record balance after Command call
        uint256 balanceAfter = address(c).balance;

        // The general rule: after Command, the balance should decrease exactly by msg.value
        // (assuming the target doesn't revert, which we can't control in fuzz)
        // More precisely: balanceAfter <= balanceBefore - amount (if call succeeds) 
        // or balanceAfter == balanceBefore (if call reverts)
        assertTrue(balanceAfter <= balanceBefore);
        assertTrue(balanceAfter >= balanceBefore - amount);
    }
}

