pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 msgVal) public {
        // Ensure the call to Command doesn't revert by using the Owner
        vm.assume(adr != address(0));
        vm.deal(address(c), 1 ether);

        // First, set up the owner to call Command
        address owner = c.Owner();
        vm.prank(owner);
        (bool success, ) = address(c).call{value: msgVal}(abi.encodeWithSignature("Command(address,bytes)", adr, data));
        vm.assume(success);

        // Now call multiplicate with msg.value exactly equal to contract balance
        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this));
        (bool reverted, ) = address(c).call{value: balanceBefore}(abi.encodeWithSignature("multiplicate(address)", adr));

        assertTrue(!reverted, "multiplicate should not revert when msg.value == balance");
    }
}

