pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 contractBalance, bytes memory data) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        contractBalance = bound(contractBalance, 1, 1e18);
        vm.deal(address(c), contractBalance);

        // Call Command with msg.value = contractBalance to forward funds
        vm.prank(caller);
        c.Command{value: contractBalance}(address(0xdead), data);

        // Now call multiplicate with msg.value at least the contract balance
        uint256 balanceBefore = address(c).balance;
        uint256 sendValue = bound(balanceBefore, balanceBefore, balanceBefore * 2); // >= balance
        vm.prank(caller);
        c.multiplicate{value: sendValue}(address(0xbeef));

        assertTrue(address(c).balance > 0);
    }
}

